class Solution { public int reachableNodes(int n,int[][] edges,int[] restricted){List<Integer>[] graph=new List[n];for(int i=0;i<n;i++)graph[i]=new ArrayList<>();for(int[] edge:edges){graph[edge[0]].add(edge[1]);graph[edge[1]].add(edge[0]);}boolean[] blocked=new boolean[n],seen=new boolean[n];for(int node:restricted)blocked[node]=true;Queue<Integer> queue=new ArrayDeque<>();queue.add(0);seen[0]=true;int answer=0;while(!queue.isEmpty()){int node=queue.poll();answer++;for(int next:graph[node])if(!seen[next]&&!blocked[next]){seen[next]=true;queue.add(next);}}return answer;} }
